const COLOR_ARRAY = Array.from(DefaultColorStyle.values)
  .filter((c) => !["red", "green", "grey"].includes(c))
  .reverse() as TLDefaultColorStyle[];

export const DISCOURSE_RELATION_SHAPE_TYPE = "discourse-relation";

const isRelationShapeType = (shapeType: string): boolean =>
  Object.values(discourseContext.relations).some((relations) =>
    relations.some((relation) => relation.id === shapeType),
  );

const isBindableDiscourseNodeShapeType = (shapeType: string): boolean =>
  shapeType === DISCOURSE_NODE_SHAPE_TYPE ||
  (!!discourseContext.nodes[shapeType] && !isRelationShapeType(shapeType));

export const getRelationColor = (
  relationName: string,
  index?: number,
): TLDefaultColorStyle => {
  if (relationName === "Supports" || relationName === "Supported By") {
    return "green";
  }

  if (relationName === "Opposes" || relationName === "Opposed By") {
    return "red";
  }

  if (relationName === "Informs" || relationName === "Informed By") {
    return "grey";
  }

  if (relationName === "Add Source") {
    return "grey";
  }

  return `${COLOR_ARRAY[index || 0]}`;
};

type ShapeWithOptionalRelationTypeId = TLShape & {
  props?: {
    relationTypeId?: string | null;
  };
};

export const getDiscourseRelationTypeId = ({
  shape,
}: {
  shape: ShapeWithOptionalRelationTypeId;
}): string => {
  return shape.props?.relationTypeId || shape.type;
};

export const getDiscourseRelationBindingType = ({
  shape,
}: {
  shape: ShapeWithOptionalRelationTypeId;
}): string => {
  return shape.type === DISCOURSE_RELATION_SHAPE_TYPE
    ? DISCOURSE_RELATION_SHAPE_TYPE
    : shape.type;
};

export const isDiscourseRelationShape = (
  shape: TLShape,
): shape is DiscourseRelationShape => {
  return (
    shape.type === DISCOURSE_RELATION_SHAPE_TYPE ||
    isRelationShapeType(shape.type)
  );
};

const getDiscourseRelationById = (
  relationTypeId: string,
): DiscourseRelation | undefined =>
  Object.values(discourseContext.relations)
    .flat()
    .find((relation) => relation.id === relationTypeId);

