  });
  return createMigrationSequence({
    sequenceId: `${SEQUENCE_ID_BASE}`,
    sequence: [
      {
        id: versions["ExtractBindings"],
        scope: "store",
        up: (oldStore) => {
          type OldArrowTerminal =
            | { type: "point"; x: number; y: number }
            | {
                type: "binding";
                boundShapeId: TLShapeId;
                normalizedAnchor: VecModel;
